function ListingDeitySelect({options,defaultValue=[]}) {
  const [selected,setSelected]=useState(defaultValue)
  const dropdownRef=useRef(null)
  const choices=[...new Set([...options,...defaultValue,...selected])]
  useEffect(()=>{
    const close=event=>{if(!dropdownRef.current?.contains(event.target))dropdownRef.current?.removeAttribute('open')}
    document.addEventListener('pointerdown',close)
    return ()=>document.removeEventListener('pointerdown',close)
  },[])
  return <div><span className="label">Other deities (optional)</span><select hidden multiple name="otherDeities" aria-label="Selected other deities" value={selected} onChange={event=>setSelected([...event.target.selectedOptions].map(option=>option.value))}>{choices.map(value=><option key={value}>{value}</option>)}</select>
    <details ref={dropdownRef} className="relative" onKeyDown={event=>{if(event.key==='Escape'){event.currentTarget.removeAttribute('open');event.currentTarget.querySelector('summary').focus()}}}>
      <summary aria-label="Other deities (optional)" className="input flex cursor-pointer list-none items-center justify-between gap-2 [&::-webkit-details-marker]:hidden"><span className={selected.length?'':'text-brown-400'}>{selected.length?selected.join(', '):'Select deities'}</span><ChevronDown size={16} className="shrink-0"/></summary>
      <div className="absolute inset-x-0 top-full z-20 mt-1 max-h-60 overflow-y-auto rounded-xl border border-brown-200 bg-white p-1 shadow-lg" role="group" aria-label="Other deity choices">{choices.map(value=><button key={value} type="button" role="checkbox" aria-checked={selected.includes(value)} onClick={()=>setSelected(current=>current.includes(value)?current.filter(item=>item!==value):[...current,value])} className="flex w-full items-center gap-2 rounded-lg px-3 py-2 text-left text-sm hover:bg-brown-50 focus:bg-brown-50 focus:outline-none"><span aria-hidden="true" className={`flex h-4 w-4 shrink-0 items-center justify-center rounded border ${selected.includes(value)?'border-saffron-500 bg-saffron-500 text-white':'border-brown-300'}`}>{selected.includes(value)&&<Check size={12}/>}</span>{value}</button>)}</div>
    </details><span className="mt-1 block text-xs text-brown-500">Select one or more deities.</span></div>
}

function ListingImagePreview({file,className=''}) {
  const [url,setUrl]=useState('')
  useEffect(()=>{
    const preview=URL.createObjectURL(file)
    setUrl(preview)
    return ()=>URL.revokeObjectURL(preview)
  },[file])
  return url?<img src={url} alt={file.name} className={className}/>:null
}

