  const saveSection=(nextStep=null)=>{const drafts=readListingDrafts();const current=drafts.find(d=>d.id===draftId)||{id:draftId,createdBy:'Devotee · Anand',sections:{},completedSections:[]};const sectionValues=controls();const listingName=step===0?(sectionValues[0]?.value||current.listingName||`Untitled ${type}`):(current.listingName||existing?.name||`Untitled ${type}`);const updated={...current,listingName,type,updatedAt:new Date().toISOString(),currentStep:nextStep??step,sections:{...current.sections,[step]:sectionValues},completedSections:[...new Set([...current.completedSections,step])].sort()};writeListingDrafts([...drafts.filter(d=>d.id!==draftId),updated]);if(!existing)sessionStorage.setItem('ta-active-listing-draft',draftId);toast(`${steps[step]} saved as draft`);if(nextStep!==null)setStep(nextStep)}
  const submitListing=()=>{saveSection();writeListingDrafts(readListingDrafts().filter(d=>d.id!==draftId));sessionStorage.removeItem('ta-active-listing-draft');onSubmit()}
