const reviewPath = (queue,id,role='moderator') => `/staff/review/${queue}/${id}?role=${role}`
const QueueTable = ({head,rows,searchKeys,filterKey,filterLabel='Status',filterOptions=[]}) => {
  const [query,setQuery]=useState(''); const [filter,setFilter]=useState('All'); const [page,setPage]=useState(1); const size=4
  const found=rows.filter(r=>(filter==='All'||String(r[filterKey])===filter)&&searchKeys.some(k=>String(r[k]||'').toLowerCase().includes(query.toLowerCase())))
  const pages=Math.max(1,Math.ceil(found.length/size)); const safePage=Math.min(page,pages); const shown=found.slice((safePage-1)*size,safePage*size)
  return <div className="card overflow-hidden"><div className="border-b border-brown-100 p-4"><label className="relative block"><Search size={16} className="absolute left-3 top-3 text-brown-400"/><input value={query} onChange={e=>{setQuery(e.target.value);setPage(1)}} placeholder="Search name, code or creator" className="input pl-9"/></label>{filterOptions.length>0&&<fieldset className="mt-3 flex flex-wrap items-center gap-2"><legend className="mr-1 inline text-xs font-semibold uppercase text-brown-500">{filterLabel}</legend>{['All',...filterOptions].map(x=><label key={x} className={`cursor-pointer rounded-full border px-3 py-1.5 text-sm font-semibold transition ${filter===x?'border-brown-900 bg-brown-900 text-white':'border-brown-200 bg-white text-brown-700 hover:bg-brown-50'}`}><input type="radio" name={`${filterLabel}-filter`} value={x} checked={filter===x} onChange={e=>{setFilter(e.target.value);setPage(1)}} className="sr-only"/>{x}</label>)}</fieldset>}</div><Table head={head} rows={shown.map(r=>r.cells)}/><div className="flex items-center justify-between border-t border-brown-100 px-4 py-3 text-sm text-brown-500"><span>{found.length?`${(safePage-1)*size+1}–${Math.min(safePage*size,found.length)} of ${found.length}`:'No matching records'}</span><div className="flex items-center gap-2"><button className="btn-g !px-3 !py-1.5" disabled={safePage===1} onClick={()=>setPage(p=>Math.max(1,p-1))}>Previous</button><span>Page {safePage} of {pages}</span><button className="btn-g !px-3 !py-1.5" disabled={safePage===pages} onClick={()=>setPage(p=>Math.min(pages,p+1))}>Next</button></div></div></div>
}
const ModeratorActions = ({queue,id,preview,toast}) => <div className="flex min-w-max flex-wrap gap-1.5"><Link target="_blank" rel="noreferrer" href={reviewPath(queue,id)} className="btn-g !px-2.5 !py-1.5 text-xs"><Eye size={13}/>View</Link>{preview&&<Link target="_blank" rel="noreferrer" href={preview} className="btn-g !px-2.5 !py-1.5 text-xs"><ExternalLink size={13}/>Preview</Link>}<button onClick={()=>toast(`${id} approved`)} className="btn !bg-emerald-50 !px-2.5 !py-1.5 text-xs text-emerald-700"><Check size={13}/>Approve</button><button onClick={()=>toast(`${id} reverted to its creator`)} className="btn !bg-saffron-50 !px-2.5 !py-1.5 text-xs text-saffron-700"><RotateCcw size={13}/>Revert</button><button onClick={()=>toast(`Message composer opened for ${id}`)} className="btn-g !px-2.5 !py-1.5 text-xs"><MessageCircle size={13}/>Message</button></div>

