/* -------- 3d. Master data: deities, categories, service types, listing types -------- */
function EditableMasterList({ title, hint, seed, toast }) {
  const [rows,setRows]=useState(seed); const [name,setName]=useState(''); const [ml,setMl]=useState('')
  const add=()=>{if(!name.trim())return; setRows(r=>[...r,{name:name.trim(),ml:ml.trim(),active:true}]); toast(`${name} added to ${title}`); setName('');setMl('')}
  const toggle=i=>setRows(r=>r.map((x,j)=>j===i?{...x,active:!x.active}:x))
  const remove=i=>{const n=rows[i].name;setRows(r=>r.filter((_,j)=>j!==i));toast(`${n} removed from ${title}`)}
  return <div className="card p-5"><h3 className="font-semibold">{title}</h3>{hint&&<p className="text-xs text-brown-500">{hint}</p>}
    <div className="mt-3"><Table head={['Name (English)','Name (Malayalam)','Active','']} rows={rows.map((r,i)=>[<b>{r.name}</b>,<span className="ml text-brown-500">{r.ml||'—'}</span>,<Toggle defaultChecked={r.active} onChange={()=>toggle(i)}/>,<button onClick={()=>remove(i)} className="text-xs text-red-600">Remove</button>])}/></div>
    <div className="mt-3 flex flex-wrap items-end gap-2"><Field label="Name (English)"><Input value={name} onChange={e=>setName(e.target.value)} placeholder="Add new…"/></Field><Field label="Name (Malayalam)" hint="Optional"><Input className="input ml" value={ml} onChange={e=>setMl(e.target.value)}/></Field><button onClick={add} className="btn-s"><Plus size={16}/>Add</button></div>
  </div>
}
