export function SAuditLogs() {
  const [tab,setTab]=useState(0); const [query,setQuery]=useState(''); const [result,setResult]=useState('All'); const [page,setPage]=useState(1); const [toast,el]=useToast()
  const rows=tab===0?userActivityLogs:adminAuditLogs
  const filtered=useMemo(()=>rows.filter(row=>(result==='All'||row.result===result)&&(!query.trim()||Object.values(row).join(' ').toLowerCase().includes(query.trim().toLowerCase()))),[rows,result,query])
  const size=4,pages=Math.max(1,Math.ceil(filtered.length/size)),safePage=Math.min(page,pages),shown=filtered.slice((safePage-1)*size,safePage*size)
  const setFilter=(setter,value)=>{setter(value);setPage(1)}
  const exportLogs=()=>{const headers=['Date & time','Name','User / staff ID','Role','Activity','Target / reference','Source / device / IP','Result'];const csv=[headers,...filtered.map(row=>[row.at,row.actor,row.id,row.role,row.event,row.target,row.source,row.result])].map(row=>row.map(quoteCsv).join(',')).join('\n');downloadDealerFile(`${tab===0?'user-activity':'admin-audit'}-logs.csv`,'text/csv;charset=utf-8',csv);toast(`${filtered.length} log records exported`)}
  return (<SShell>{el}<H t="Activity & audit logs" s="Read-only records of user activity, staff decisions and protected administrator changes" right={<button onClick={exportLogs} className="btn-s"><Download size={16}/>Export filtered CSV</button>}/><Tabs tabs={['User activity logs','Admin audit logs']} at={tab} set={value=>{setTab(value);setQuery('');setResult('All');setPage(1)}}/>
    <div className="card overflow-hidden"><div className="space-y-3 border-b border-brown-100 p-4"><label className="relative block"><Search size={16} className="absolute left-3 top-3 text-brown-400"/><Input value={query} onChange={e=>setFilter(setQuery,e.target.value)} placeholder="Search name, ID, activity, listing, transaction, device or IP" className="pl-9"/></label><fieldset className="flex flex-wrap gap-2"><legend className="mb-1 text-xs font-semibold uppercase text-brown-500">Result</legend>{['All',...new Set(rows.map(row=>row.result))].map(option=><label key={option} className={`cursor-pointer rounded-full border px-3 py-1.5 text-sm font-semibold ${result===option?'border-brown-900 bg-brown-900 text-white':'border-brown-200 bg-white text-brown-700'}`}><input type="radio" name="audit-result" className="sr-only" checked={result===option} onChange={()=>setFilter(setResult,option)}/>{option}</label>)}</fieldset></div>
      <div className="overflow-x-auto"><Table head={['Date & time','User / staff','Role','Activity','Target / reference','Source / device / IP','Result']} rows={shown.map(row=>[<span className="whitespace-nowrap">{row.at}</span>,<span><b>{row.actor}</b><small className="block text-brown-500">{row.id}</small></span>,row.role,row.event,<span className="min-w-[190px]">{row.target}</span>,<span className="text-xs">{row.source}</span>,<Pill tone={row.result==='Success'?'ok':row.result==='Blocked'?'err':row.result==='Needs action'||row.result==='Pending review'?'warn':'info'}>{row.result}</Pill>])}/></div>
      <div className="flex flex-col gap-3 border-t border-brown-100 px-4 py-3 text-sm text-brown-500 sm:flex-row sm:items-center sm:justify-between"><span>{filtered.length?`${(safePage-1)*size+1}–${Math.min(safePage*size,filtered.length)} of ${filtered.length}`:'No matching log records'}</span><div className="flex items-center gap-2"><button className="btn-g !px-3 !py-1.5" disabled={safePage===1} onClick={()=>setPage(value=>Math.max(1,value-1))}>Previous</button><span>Page {safePage} of {pages}</span><button className="btn-g !px-3 !py-1.5" disabled={safePage===pages} onClick={()=>setPage(value=>Math.min(pages,value+1))}>Next</button></div></div></div>
    <div className="mt-4 rounded-xl bg-blue-50 p-3 text-sm text-blue-900"><ShieldCheck size={15} className="mr-1 inline"/>Audit records are immutable. Exports respect the current tab, search and result filter.</div></SShell>)
}

